const e = $input.first().json;
const hoje = '1998-05-06';
const data = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? s : '';
const inicio = data(e.inicio);
const fim = data(e.fim);
const inicios = [inicio, data(e.comparar_inicio)].filter(Boolean).sort();
const fins = [fim, data(e.comparar_fim)].filter(Boolean).sort();
const de = inicios[0] || '';
const ate = fins[fins.length - 1] || '';
const diaSeguinte = s => new Date(Date.parse(s + 'T00:00:00Z') + 86400000).toISOString().slice(0, 10);
const filtros = [];
if (de) filtros.push('OrderDate ge ' + de + 'T00:00:00Z');
if (ate) filtros.push('OrderDate lt ' + diaSeguinte(ate) + 'T00:00:00Z');
const expand = 'Customer($select=CompanyName),Employee($select=FirstName,LastName),Order_Details($select=ProductID,UnitPrice,Quantity,Discount;$expand=Product($select=ProductName;$expand=Category($select=CategoryName)))';
let url = 'https://services.odata.org/V4/Northwind/Northwind.svc/Orders?$format=json&$select=OrderID,OrderDate,Freight,ShipCountry&$expand=' + encodeURIComponent(expand);
if (filtros.length) url += '&$filter=' + encodeURIComponent(filtros.join(' and '));
return [{ json: { url, hoje, inicio: inicio || '1996-07-04', fim: fim || hoje, base_de: de || '1996-01-01', base_ate: ate || '1998-12-31' } }];

const m = $('Monta consulta').first().json;
const paginas = $input.all();
const brutos = paginas.flatMap(p => p.json.value || []);
const pedidos = brutos.map(o => ({ pedido: o.OrderID, data: o.OrderDate.slice(0, 10), frete: o.Freight }));
const linhas = brutos.flatMap(o => (o.Order_Details || []).map(d => ({
  pedido: o.OrderID,
  data: o.OrderDate.slice(0, 10),
  mes: o.OrderDate.slice(0, 7),
  cliente: o.Customer ? o.Customer.CompanyName : 'Sem cliente',
  pais: o.ShipCountry,
  vendedor: o.Employee ? o.Employee.FirstName + ' ' + o.Employee.LastName : 'Sem vendedor',
  produto: d.Product.ProductName,
  categoria: d.Product.Category ? d.Product.Category.CategoryName : 'Sem categoria',
  quantidade: d.Quantity,
  liquido: d.UnitPrice * d.Quantity * (1 - d.Discount)
})));
return [{ json: { ...m, paginas: paginas.length, pedidos, linhas } }];

const d = $('Normaliza vendas').first().json;
const inicio = query.inicio || d.inicio;
const fim = query.fim || d.fim;
if (inicio < d.base_de || fim > d.base_ate) return JSON.stringify({ status: 'PERIODO_NAO_CARREGADO', carregado: [d.base_de, d.base_ate] });
const noPeriodo = x => x.data >= inicio && x.data <= fim;
const linhas = d.linhas.filter(noPeriodo);
const pedidos = d.pedidos.filter(noPeriodo);
if (!pedidos.length) return JSON.stringify({ status: 'SEM_DADOS', inicio, fim });
const r2 = v => Math.round(v * 100) / 100;
const dias = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000) + 1;
const faturamento = linhas.reduce((s, x) => s + x.liquido, 0);
const frete = pedidos.reduce((s, x) => s + x.frete, 0);
const corridos = dias(inicio, fim < d.hoje ? fim : d.hoje);
const saida = { status: 'OK', inicio, fim, faturamento: r2(faturamento), pedidos: pedidos.length, ticket_medio: r2(faturamento / pedidos.length), frete: r2(frete), dias_corridos: corridos, media_diaria: r2(faturamento / corridos) };
if (fim > d.hoje) {
  saida.periodo_parcial = true;
  saida.dados_ate = d.hoje;
  saida.dias_do_periodo = dias(inicio, fim);
  saida.projecao = r2(faturamento / corridos * saida.dias_do_periodo);
}
return JSON.stringify(saida);

const d = $('Normaliza vendas').first().json;
const dimensao = query.dimensao;
if (!['produto', 'categoria', 'vendedor', 'cliente', 'pais', 'mes'].includes(dimensao)) return JSON.stringify({ status: 'PARAMETRO_INVALIDO', campo: 'dimensao' });
const inicio = query.inicio || d.inicio;
const fim = query.fim || d.fim;
if (inicio < d.base_de || fim > d.base_ate) return JSON.stringify({ status: 'PERIODO_NAO_CARREGADO', carregado: [d.base_de, d.base_ate] });
const linhas = d.linhas.filter(x => x.data >= inicio && x.data <= fim);
if (!linhas.length) return JSON.stringify({ status: 'SEM_DADOS', inicio, fim });
const r2 = v => Math.round(v * 100) / 100;
const grupos = {};
for (const l of linhas) {
  const chave = l[dimensao];
  grupos[chave] = grupos[chave] || { nome: chave, valor: 0, quantidade: 0, pedidos: new Set() };
  grupos[chave].valor += l.liquido;
  grupos[chave].quantidade += l.quantidade;
  grupos[chave].pedidos.add(l.pedido);
}
const total = linhas.reduce((s, x) => s + x.liquido, 0);
const lista = Object.values(grupos);
if (dimensao === 'mes') lista.sort((a, b) => a.nome.localeCompare(b.nome));
else lista.sort((a, b) => query.ordem === 'menor' ? a.valor - b.valor : b.valor - a.valor);
const limite = dimensao === 'mes' ? lista.length : Math.min(Number(query.limite) || 10, 30);
const posicoes = lista.slice(0, limite).map((g, i) => ({ posicao: i + 1, nome: g.nome, faturamento: r2(g.valor), participacao_pct: r2(g.valor / total * 100), pedidos: g.pedidos.size, quantidade: g.quantidade }));
return JSON.stringify({ status: 'OK', inicio, fim, dimensao, total_geral: r2(total), grupos_no_periodo: lista.length, posicoes });

const d = $('Normaliza vendas').first().json;
const inicio = query.inicio || d.inicio;
const fim = query.fim || d.fim;
if (inicio < d.base_de || fim > d.base_ate) return JSON.stringify({ status: 'PERIODO_NAO_CARREGADO', carregado: [d.base_de, d.base_ate] });
const linhas = d.linhas.filter(x => x.data >= inicio && x.data <= fim);
if (!linhas.length) return JSON.stringify({ status: 'SEM_DADOS', inicio, fim });
const r2 = v => Math.round(v * 100) / 100;
const porProduto = {};
for (const l of linhas) porProduto[l.produto] = (porProduto[l.produto] || 0) + l.liquido;
const itens = Object.entries(porProduto).map(([nome, valor]) => ({ nome, valor })).sort((a, b) => b.valor - a.valor);
const total = itens.reduce((s, x) => s + x.valor, 0);
let acumulado = 0;
const classes = { A: { produtos: 0, valor: 0 }, B: { produtos: 0, valor: 0 }, C: { produtos: 0, valor: 0 } };
for (const i of itens) {
  const antes = acumulado / total * 100;
  i.classe = antes < 80 ? 'A' : antes < 95 ? 'B' : 'C';
  classes[i.classe].produtos += 1;
  classes[i.classe].valor += i.valor;
  acumulado += i.valor;
}
const resumo = ['A', 'B', 'C'].map(c => ({ classe: c, produtos: classes[c].produtos, faturamento: r2(classes[c].valor), participacao_pct: r2(classes[c].valor / total * 100) }));
const principais = itens.filter(i => i.classe === 'A').slice(0, 5).map(i => ({ nome: i.nome, faturamento: r2(i.valor) }));
return JSON.stringify({ status: 'OK', inicio, fim, total_geral: r2(total), produtos_vendidos: itens.length, classes: resumo, principais_da_classe_a: principais });

const d = $('Normaliza vendas').first().json;
const datas = [query.atual_inicio, query.atual_fim, query.base_inicio, query.base_fim];
if (datas.some(x => !x)) return JSON.stringify({ status: 'PARAMETRO_INVALIDO', campo: 'datas' });
if (datas.some(x => x < d.base_de || x > d.base_ate)) return JSON.stringify({ status: 'PERIODO_NAO_CARREGADO', carregado: [d.base_de, d.base_ate] });
const r2 = v => Math.round(v * 100) / 100;
const medir = (ini, fim) => {
  const dentro = x => x.data >= ini && x.data <= fim;
  const faturamento = d.linhas.filter(dentro).reduce((s, x) => s + x.liquido, 0);
  const pedidos = d.pedidos.filter(dentro).length;
  return { inicio: ini, fim, faturamento, pedidos, ticket_medio: pedidos ? faturamento / pedidos : 0 };
};
const variacao = (a, b) => ({ diferenca: r2(a - b), percentual: b ? r2((a - b) / b * 100) : null });
const atual = medir(query.atual_inicio, query.atual_fim);
const base = medir(query.base_inicio, query.base_fim);
if (!atual.pedidos && !base.pedidos) return JSON.stringify({ status: 'SEM_DADOS' });
const fmt = p => ({ ...p, faturamento: r2(p.faturamento), ticket_medio: r2(p.ticket_medio) });
return JSON.stringify({ status: 'OK', atual: fmt(atual), base: fmt(base), variacao: { faturamento: variacao(atual.faturamento, base.faturamento), pedidos: variacao(atual.pedidos, base.pedidos), ticket_medio: variacao(atual.ticket_medio, base.ticket_medio) } });
